def map_shell(extra='', title='شبكة المرافق', summary=False):
    top = '<div class="atlas-summary"><div><b data-count="all">8</b><span>مرافق في النطاق</span></div><div><b data-count="free">3</b><span>متاحة في اليوم</span></div><div><b data-count="pending">2</b><span>قيد المراجعة</span></div></div>' if summary else f'<div class="map-title flex">{icon("map")}<span>{title}</span></div>'
    return f'''<section class="map-shell {extra}" aria-label="خريطة مواقع الشركة الافتراضية"><div id="map" class="map"></div><div class="map-top">{top}<div class="map-tools"><button class="icon-btn" onclick="map.zoomIn()" title="تكبير" aria-label="تكبير">+</button><button class="icon-btn" onclick="map.zoomOut()" title="تصغير" aria-label="تصغير">−</button><button class="icon-btn" onclick="fitSites()" title="عرض المواقع" aria-label="عرض جميع المواقع">{icon('pin')}</button><button class="icon-btn" onclick="toggleLayers()" title="الطبقات" aria-label="إظهار الطبقات">{icon('layers')}</button></div></div><div id="layers" class="map-layers" hidden><h3>طبقات العرض</h3><label><input type="checkbox" id="labelsToggle" checked onchange="drawSites()">أسماء المرافق</label><label><input type="checkbox" id="boundsToggle" checked onchange="drawSites()">حدود المرافق الافتراضية</label><label><input type="checkbox" id="geoToggle" onchange="toggleGeo(this.checked)">خريطة جغرافية مضمّنة</label><p class="demo-caption">الخلفية الجغرافية نسخة إقليمية توضيحية من بيانات مفتوحة. المرافق والحدود والطلبات افتراضية.</p></div><div class="map-bottom"><div class="map-legend"><span><i class="dot" style="color:var(--green)"></i>متاح</span><span><i class="dot" style="color:var(--orange)"></i>طلب معلّق</span><span><i class="dot" style="color:var(--red)"></i>مشغول</span></div></div><div class="map-note" id="mapNote">خريطة تخطيطية افتراضية · Leaflet</div>__MAP_EXTRA__</section>'''

def detail_card(cls='', button=True):
    return f'''<div class="detail-card {cls}"><div class="flex spread"><span class="eyebrow" data-detail="code">FACILITY / 02</span><span class="pill" data-detail="status"></span></div><h2 data-detail="name"></h2><p class="muted micro" data-detail="group"></p><dl class="detail-grid"><div><dt>تصنيف المرفق</dt><dd data-detail="type"></dd></div><div><dt>السعة</dt><dd data-detail="capacity"></dd></div><div><dt>الموقع الرئيسي</dt><dd>مجمع الشركة</dd></div><div><dt>اليوم المعروض</dt><dd data-detail="day"></dd></div></dl><div class="flex spread micro"><span class="muted">إشغال تجريبي</span><b data-detail="usage"></b></div><div class="progress"><i data-detail="bar"></i></div>{'<button class="btn primary" style="width:100%;margin-top:17px" onclick="openRequest()">'+icon('plus')+'طلب على هذا المرفق</button>' if button else ''}<p class="demo-caption" style="margin-top:10px">تحديد المرفق لا ينشئ حجزاً. الطلب يحتاج مراجعة واعتماداً.</p></div>'''

def header(view):
    items=''.join(f'<a href="{c["slug"]}" class="{"active" if c["id"]==view else ""}">{c["id"]:02}</a>' for c in CONCEPTS)
    brand=f'<a class="brand" href="index.html"><span class="brand-mark">{icon("map")}</span><span><strong>MOVER</strong><small>إدارة المواقع والمرافق</small></span></a>'
    top=f'''<header class="topbar">{brand}<nav class="topnav" aria-label="التصورات"><a href="01-atlas.html" class="{'active' if view==1 else ''}">الخريطة</a><a href="02-request.html" class="{'active' if view==2 else ''}">الطلبات</a><a href="03-review.html" class="{'active' if view==3 else ''}">المراجعة</a><a href="04-structure.html" class="{'active' if view==4 else ''}">الهيكل</a><a href="05-calendar.html" class="{'active' if view==5 else ''}">الإشغال</a></nav><div class="grow"></div><a href="questions.html" class="btn ghost small">قرارات التصميم</a><button class="btn primary" onclick="openRequest()">{icon('plus')}طلب جديد</button><div class="flex"><div class="avatar">م م</div><span class="user-label">مستخدم تجريبي<br><span class="muted tiny">مدير المرافق</span></span></div></header>'''
