def build_pages():
    bodies=[page1(),page2(),page3(),page4(),page5()]
    for c,body in zip(CONCEPTS,bodies):
        html='<!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="light"><title>MOVER / '+c['name']+'</title><meta name="description" content="تصور تفاعلي لإدارة مرافق الشركة — بيانات افتراضية"><style>'+FONT+LEAFLET_CSS+CSS+'</style></head><body class="view'+str(c['id'])+'">'+body+COMMON_DIALOG+'<script>/* Leaflet 1.9.4 — '+LICENSE.replace('*/','* /')+' */\n'+LEAFLET+'</script><script>'+JS.replace('__VIEW__',str(c['id'])).replace('__BASEMAP_B64__',BASEMAP_B64)+'</script></body></html>'
        (DIST/c['slug']).write_text(html)

