def mini(c):
    roads='<svg viewBox="0 0 400 250" preserveAspectRatio="none" aria-hidden="true"><g fill="none" stroke="#fcfff4" stroke-width="7" opacity=".6"><path d="M-20 200 180 130 420 180M20-10 190 100 310 270M-10 60 200 70 420 10M280-10 250 110 420 240"/></g><g fill="'+c['color']+'" stroke="white" stroke-width="2"><circle cx="100" cy="100" r="7"/><circle cx="250" cy="80" r="7"/><circle cx="185" cy="185" r="7"/><circle cx="320" cy="155" r="7"/></g></svg>'
    side='<div class="mini-side">'+''.join('<i></i>' for _ in range(7))+'</div>'
    doc='<div class="mini-document">'+''.join('<i></i>' for _ in range(9))+'</div>' if c['id']==3 else ''
    cl=['atlas','flow','desk','nexus','tempo'][c['id']-1]
    extra='<div class="mini-table"></div>' if c['id']==4 else '<div class="mini-time"><i></i><i></i><i></i></div>' if c['id']==5 else ''
    return f'<div class="mini" style="--mini:{["#dce8df","#e6eddf","#eae1d4","#dde4f0","#e5e0f0"][c["id"]-1]};--tone:{c["color"]}"><div class="mini-app mini-{cl}"><div class="mini-top"><b>MOVER / {c["en"]}</b><i></i></div><div class="mini-main">{side}{doc}<div class="mini-map">{roads}<span class="tag">مرافق الشركة</span><div class="mini-float"><i></i><i></i><i></i></div></div></div>{extra}</div></div>'

def gallery_header():
    return '<header class="mast"><a class="logo" href="index.html">MOVER.</a><small>المكان · الإجراءات · القرار</small><nav><a href="index.html">التصاميم الخمسة</a><a href="questions.html">البحث والأسئلة</a></nav></header>'

def wrap_doc(title,body,script=''):
    return '<!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+title+'</title><style>'+FONT+GALLERY_CSS+'</style></head><body><div class="wrap">'+gallery_header()+body+'<footer><span>MOVER / CONCEPT LAB — 28 OCT 2026</span><span>نماذج أولية لإدارة مرافق الشركة · بيانات افتراضية</span></footer></div><script>'+script+'</script></body></html>'

def build_gallery():
    cards=''.join('<article class="card">'+mini(c)+f'<div class="card-body"><div class="card-meta">{c["en"]} / 0{c["id"]}<span>{c["label"]}</span></div><h2>{c["name"]}</h2><p>{c["desc"]}</p><div class="card-links"><a class="open-link" href="{c["slug"]}">افتح النموذج التفاعلي ←</a><a class="download" href="{c["slug"]}" download>تنزيل HTML ↙</a></div></div></article>' for c in CONCEPTS)
    body='''<section class="hero"><div><p class="eyebrow">FIVE WAYS TO SEE YOUR ORGANIZATION</p><h1>ابدأ بالمكان.<br>وشاهد <em>المؤسسة كاملة.</em></h1><p>خمسة تصورات مختلفة لتجربة إدارة المواقع والمرافق والطلبات. اختر طريقة العمل التي تناسب فريقك، ثم نبني عليها.</p></div><aside><b>05</b><span>تصورات HTML تفاعلية<br>اتجاهات مختلفة، بيانات مشتركة</span></aside></section><div class="intro-line"><span><i class="dot"></i>خريطة تفاعلية في كل تصميم</span><span>سحب وتكبير · اختيار مرفق · تصفية · محاكاة إجراءات</span></div><main class="cards">'''+cards+'''</main><section class="research"><div><h2>قبل البناء، نحسم القرارات الصحيحة.</h2><p>بحث في أدوات الخرائط والصلاحيات والإجراءات، مع 30 سؤالاً حول بيانات المواقع والتعارض الزمني والهيكل والمراجعات. يمكنك تدوين إجاباتك وتنزيلها.</p></div><div class="actions"><a class="button" href="questions.html">البحث والأسئلة الثلاثون ←</a><a class="button light" href="mover-five-concepts.zip" download>تنزيل النماذج الخمسة</a></div></section><p style="font-size:11px;color:#8b998b;margin:20px 0 30px">الخريطة الجغرافية الإقليمية مضمّنة من بيانات OpenFreeMap / OpenStreetMap وتعمل دون اتصال في متصفح حديث، مع خيار رسم تخطيطي. المرافق والحدود والطلبات افتراضية؛ والخريطة التوضيحية ليست للملاحة. كل الإجراءات محاكاة في المتصفح.</p>'''
    (DIST/'index.html').write_text(wrap_doc('MOVER — خمسة تصورات على الخريطة',body))

def build_questions():
    n=0;groups=[]
    for title,qs in QUESTIONS:
        text='<section class="question-group"><h2>'+title+'</h2>'
        for q in qs:
            n+=1;text+=f'<div class="question"><label for="q{n}"><b>{n:02}</b><span>{q}</span></label><textarea id="q{n}" data-question="{q}" placeholder="إجابتك، أو اكتب: اقترح أنت…" oninput="saveAnswers()"></textarea></div>'
        groups.append(text+'</section>')
    table='''<div class="comparison-wrap"><table class="source-table"><thead><tr><th>المكوّن</th><th>ما ثبت في المصادر</th><th>الاستخدام المقترح</th></tr></thead><tbody>
<tr><td><a href="https://maplibre.org/maplibre-gl-js/docs/examples/" target="_blank" rel="noopener">MapLibre GL JS</a></td><td>أمثلة تفاعلية للطبقات وGeoJSON والتصفية والتجميع.</td><td>واجهة خرائط مخصصة عندما تكون تجربة الخريطة هي الأساس.</td></tr>
<tr><td><a href="https://openlayers.org/en/latest/examples/draw-and-modify-features.html" target="_blank" rel="noopener">OpenLayers</a></td><td>مثال رسمي لرسم المعالم وتعديلها.</td><td>مرشح عند الحاجة إلى أدوات GIS أو مصادر خرائط مؤسسية؛ يختبر بحسب البيانات.</td></tr>
<tr><td><a href="https://geonode.org/" target="_blank" rel="noopener">GeoNode</a></td><td>منصة GIS مفتوحة المصدر لنشر الطبقات والخرائط، وإدارة الموارد ومشاركتها.</td><td>مرجع عملي لإدارة بيانات الخريطة؛ ليست نظام طلبات نقل جاهزاً.</td></tr>
<tr><td><a href="https://openfreemap.org/quick_start/" target="_blank" rel="noopener">OpenFreeMap</a></td><td>خدمة خرائط مفتوحة تتيح استخدام المصدر العام أو الاستضافة الذاتية.</td><td>المصدر الذي أُخذت منه نسخة الخريطة المضمّنة؛ المصدر العام لا يقدم ضمان مستوى خدمة مؤسسياً.</td></tr><tr><td><a href="https://postgis.net/docs/using_postgis_dbmanagement.html" target="_blank" rel="noopener">PostGIS</a></td><td>أنواع بيانات مكانية ومرجعيات إحداثيات وفهارس مكانية.</td><td>مرشح لحفظ هندسة المرافق. تصميم الحجوزات والفترات يحتاج عملاً مستقلاً.</td></tr>
<tr><td><a href="https://openfga.dev/docs/modeling/parent-child" target="_blank" rel="noopener">OpenFGA</a></td><td>نمذجة علاقات الأصل والفرع وتأثيرها في الوصول.</td><td>صلاحيات بحسب الجهة والمورد؛ لا يغني عن تسجيل الدخول أو سجل القرارات.</td></tr>
<tr><td><a href="https://www.flowable.com/open-source/docs/bpmn/ch07b-BPMN-Constructs/" target="_blank" rel="noopener">Flowable</a></td><td>مهام بشرية، إسناد إلى مستخدمين أو مجموعات، ومواعيد استحقاق.</td><td>محرك مرشح لدورة المراجعات. نقيّم تشغيله وتكامله قبل اعتماده.</td></tr>
<tr><td><a href="https://docs.qfield.org/reference/qfieldcloud/system/" target="_blank" rel="noopener">QField / QFieldCloud</a></td><td>توثيق أوضاع العمل دون اتصال ومزامنة البيانات.</td><td>مرجع إذا ظهر احتياج لجمع بيانات مرافق ميدانياً؛ ليس شرطاً للنسخة الأولى.</td></tr>
<tr><td><a href="https://leafletjs.com/reference.html" target="_blank" rel="noopener">Leaflet</a></td><td>خرائط تفاعلية، طبقات، علامات، وأشكال هندسية.</td><td>مستخدم فعلياً في النماذج مع نسخة إقليمية مضمّنة من بيانات OpenFreeMap. لا يحسم مكتبة نظام الإنتاج.</td></tr>
</tbody></table></div>'''
    recommendations='''<div class="research-notes" id="research"><p class="eyebrow">RESEARCH / PRACTICAL DECISIONS</p><h2>من شاشة خريطة إلى إدارة مواقع فعلية</h2><p>هذه توصيات تصميمية مستخلصة من البحث، وليست مزايا تأتي تلقائياً بمجرد تركيب مكتبة.</p><ol><li><b>سجل موحد للمرفق:</b> رقم ثابت، جهة مسؤولة، حدود أو نقطة، مبانٍ تابعة، ومصدر آخر تحديث.</li><li><b>المكان والوقت معاً:</b> تعرض الخريطة إشغال المرفق في التاريخ المختار، بينما تبقى حالة الطلب منفصلة.</li><li><b>حجز آمن عند التزامن:</b> يعاد التحقق في الخادم عند الاعتماد حتى لا يعتمد طلبان على المورد الحصري والفترة نفسها.</li><li><b>الخريطة والقائمة مترابطتان:</b> اختيار أي منهما يحدد العنصر نفسه في الآخر، مع حفظ المرشحات.</li><li><b>كل قرار له سبب:</b> الإرجاع يحدد الحقول الناقصة، والاعتماد يرتبط بنسخة محددة من الطلب.</li><li><b>مصدر البيانات ظاهر:</b> آخر تحديث وحدود الدقة والجهة المالكة للبيانات؛ لا نعرض بيانات قديمة كأنها حية.</li><li><b>إعادة تحقق بعد التغيير:</b> تغيير الفترة أو المرفق أو السعة المطلوبة قد يستوجب إعادة المراجعة.</li><li><b>اعتماد ثم تنفيذ:</b> المرحلة الأخيرة تسجل الاستلام والتنفيذ والإغلاق، بدلاً من اعتبار الاعتماد نهاية العمل.</li></ol><h2>مشاريع ومكتبات جرى التحقق منها</h2>'''+table+'''<div class="source-notice">لا أتعامل مع مكتبة الخرائط على أنها مزود بيانات مجاني بلا حدود. <a href="https://operations.osmfoundation.org/policies/tiles/" target="_blank" rel="noopener" style="text-decoration:underline">سياسة OpenStreetMap</a> تذكر أن خوادم البلاطات لها شروط استخدام ولا تقدم ضمان توافر. النسخة المؤسسية تحتاج مصدراً مناسباً لحجمها وسياسة بياناتها.</div><div class="recommend"><b>الترشيح المبدئي:</b><p>نواة تجربة من «أطلس المواقع» مع نموذج «رحلة الطلب»، وصندوق «مكتب المراجعة»، وتصفية «المؤسسة والمكان»، وإشغال «الوقت والمكان». اختيار المكونات التقنية النهائي ينتظر بيانات الخرائط ونطاق الصلاحيات وطريقة الاستضافة.</p></div></div>'''
    comparisons='''<div class="comparison-wrap"><table class="compare"><thead><tr><th>التصور</th><th>بداية الاستخدام</th><th>أقوى تجربة فيه</th></tr></thead><tbody>'''+''.join(f'<tr><td><a href="{c["slug"]}">{c["name"]} ←</a></td><td>{c["label"]}</td><td>{c["desc"]}</td></tr>' for c in CONCEPTS)+'''</tbody></table></div>'''
    body='''<section class="decision-hero"><p class="eyebrow">DESIGN DECISIONS / 30 QUESTIONS</p><h1>أسئلة تحسم شكل النظام، وطريقة عمله.</h1><p>ابدأ بإجابات تقريبية. الهدف تحديد قرارات البيانات والخريطة والموافقات قبل تثبيت التقنية أو التقدير الزمني.</p></section><nav class="decision-nav"><a href="#research">نتائج البحث</a><a href="#comparison">مقارنة التصاميم</a><a href="#questions">الأسئلة الثلاثون</a></nav>'''+recommendations+'<section id="comparison"><h2 style="font-size:24px">أي تصور يخدم كل دور؟</h2>'+comparisons+'</section><section id="questions"><div class="questions-intro"><h2>الأسئلة الثلاثون</h2><p>الإجابات تحفظ في هذا المتصفح إن سمحت إعداداته بذلك. نزّل نسخة منها للاحتفاظ بها أو إرسالها في المحادثة.</p></div><div class="question-grid">'+''.join(groups)+'''</div></section><div class="decision-actions"><span id="saveStatus" class="save-status">الإجابات محلية في المتصفح</span><div><button class="button" onclick="exportAnswers()">تنزيل إجاباتي</button><a class="button light" href="index.html">العودة للتصاميم</a></div></div>'''
    js=r'''let answerKey='mover-concepts-answers-v1';let fields=[...document.querySelectorAll('[data-question]')];try{let stored=JSON.parse(localStorage.getItem(answerKey)||'{}');fields.forEach(f=>f.value=stored[f.id]||'')}catch(e){document.getElementById('saveStatus').textContent='الحفظ المحلي غير متاح — استخدم التنزيل'}function saveAnswers(){let a=Object.fromEntries(fields.map(f=>[f.id,f.value]));try{localStorage.setItem(answerKey,JSON.stringify(a));document.getElementById('saveStatus').textContent='حُفظ محلياً · '+fields.filter(f=>f.value.trim()).length+' / 30 إجابة'}catch(e){document.getElementById('saveStatus').textContent='التخزين غير متاح — نزّل إجاباتك'}}function exportAnswers(){let t='# MOVER — إجابات قرارات التصميم\n\n'+fields.map((f,i)=>(i+1)+'. '+f.dataset.question+'\n\n'+(f.value.trim()||'لم تتم الإجابة')+'\n').join('\n');let u=URL.createObjectURL(new Blob([t],{type:'text/markdown;charset=utf-8'})),a=document.createElement('a');a.href=u;a.download='mover-design-answers.md';a.click();setTimeout(()=>URL.revokeObjectURL(u),500)}'''
    (DIST/'questions.html').write_text(wrap_doc('MOVER — البحث و30 سؤالاً',body,js))

def build_zip():
    with zipfile.ZipFile(DIST/'mover-five-concepts.zip','w',zipfile.ZIP_DEFLATED) as z:
        for p in sorted(DIST.glob('*.html')):z.write(p,p.name)
        z.writestr('README.txt','MOVER — Five interactive HTML concepts\nOpen index.html in a browser.\nAll facilities, boundaries, requests, and decisions are fictional.\nLeaflet is embedded. Offline schematic maps are embedded.\nAn illustrative regional geographic map from OpenFreeMap / OpenMapTiles / OpenStreetMap is embedded. It runs offline in modern browsers supporting DecompressionStream. It is not a navigation map. All facility names, positions, boundaries, requests, and decisions are fictional.\nDemo saves use browser-local storage only. No server or real approval.\nResearch and thirty questions: questions.html\n')
        z.writestr('LEAFLET-LICENSE.txt',LICENSE)
        for name in []:
            if (ASSETS/name).exists():z.write(ASSETS/name,name)
        z.write(ROOT/'basemap.geojson','basemap.geojson')
        z.write(ROOT/'basemap.svg','basemap.svg')
        z.writestr('MAP-DATA-LICENSE.txt','OpenFreeMap / OpenMapTiles / OpenStreetMap contributors\nOpenStreetMap data is licensed under ODbL.\nhttps://www.openstreetmap.org/copyright\nhttps://opendatacommons.org/licenses/odbl/1-0/\nThis regional illustrative extract omits minor roads and buildings. It is not suitable for navigation.\nSource and tile date are retained in basemap.geojson metadata.\n')
        z.writestr('FONT-SOURCE.txt','Noto Sans Arabic / Google Fonts\nhttps://fonts.google.com/noto/specimen/Noto+Sans+Arabic\nSIL Open Font License 1.1\n')
        if (ROOT/'FONT-LICENSE.txt').exists():z.write(ROOT/'FONT-LICENSE.txt','FONT-LICENSE.txt')

if __name__=='__main__':
    build_pages();build_gallery();build_questions();shutil.copy2(ROOT/'basemap.geojson',DIST/'basemap.geojson');build_zip()
    print(json.dumps({'html_files':[p.name for p in DIST.glob('*.html')],'archive_bytes':(DIST/'mover-five-concepts.zip').stat().st_size,'font_embedded':bool(FONT)},ensure_ascii=False))
